// Unit test for source-mode ccord_av_stream (ccord_av_stream_open_source): probing and demuxing on a demux thread
// that reads through a ccord_av_source which may be slow, blocked or failing. The fixture is a 200x150, 3 s, 10 fps
// H.264 + AAC MP4 (ffmpeg testsrc + sine, ~19 KB, moov at the end, a keyframe every 5 frames, one chunk per sample
// run). Variants are built at run time: moov moved to the front ("fast start") and 48 KiB gaps inserted between
// chunk groups, so reading the clip needs many read_at calls far apart (the AVIO buffer is 32 KiB).
// Callbacks run on the demux thread: they only touch the source's own mutex-protected state, never CT_CHECK.
