#include <ccord/core/clock.h>
#include <ccord/render/av_stream.h>

#include "ccord_test.h"

#define CLIP_W 200
#define CLIP_H 150
#define GAP_BYTES (48u * 1024u)
#define MAX_CALL_MS 20u   // the design says 5 ms; this leaves room for sanitizer builds and a loaded machine

