// ---- fixture variants ----

static uint32_t be32(const uint8_t *p)
{
  return ((uint32_t)p[0] << 24) | ((uint32_t)p[1] << 16) | ((uint32_t)p[2] << 8) | (uint32_t)p[3];
}

static void put_be32(uint8_t *p, uint32_t v)
{
  p[0] = (uint8_t)(v >> 24);
  p[1] = (uint8_t)(v >> 16);
  p[2] = (uint8_t)(v >> 8);
  p[3] = (uint8_t)v;
}

static int cmp_u32(const void *a, const void *b)
{
  uint32_t x = *(const uint32_t *)a, y = *(const uint32_t *)b;
  return x < y ? -1 : x > y;
}

// Rebuilds k_clip_end as [ftyp][moov][mdat] (faststart) or [ftyp][mdat][moov], with `gap` zero bytes inserted before
// every 4th chunk and every chunk offset patched to match. Returns a ccord_malloc'd buffer.
static uint8_t *build_clip(bool faststart, size_t gap, size_t *out_n)
{
  const uint8_t *in = k_clip_end;
  size_t n = sizeof k_clip_end, ftyp_n = 0, mdat_o = 0, mdat_n = 0, moov_o = 0, moov_n = 0;
  for (size_t o = 0; o + 8 <= n;) {
    uint32_t sz = be32(in + o);
    if (sz < 8 || o + sz > n) return nullptr;
    if (!memcmp(in + o + 4, "ftyp", 4) && o == 0) ftyp_n = sz;
    else if (!memcmp(in + o + 4, "mdat", 4)) mdat_o = o, mdat_n = sz;
    else if (!memcmp(in + o + 4, "moov", 4)) moov_o = o, moov_n = sz;
    o += sz;
  }
  if (!ftyp_n || !mdat_n || !moov_n) return nullptr;
  uint8_t *moov = ccord_malloc(moov_n);
  if (!moov) return nullptr;
  memcpy(moov, in + moov_o, moov_n);
  size_t epos[256], ne = 0;
  uint32_t eval[256], uniq[256];
  for (size_t i = 4; i + 12 <= moov_n; i++) {   // every "stco" tag: size(4) tag(4) flags(4) count(4) entries
    if (memcmp(moov + i, "stco", 4) != 0) continue;
    uint32_t cnt = be32(moov + i + 8);
    for (uint32_t k = 0; k < cnt && ne < 256 && i + 12 + 4u * (k + 1u) <= moov_n; k++, ne++) {
      epos[ne] = i + 12 + 4u * k;
      eval[ne] = be32(moov + epos[ne]);
    }
  }
  memcpy(uniq, eval, ne * sizeof *uniq);
  qsort(uniq, ne, sizeof *uniq, cmp_u32);
  size_t nu = 0;
  for (size_t i = 0; i < ne; i++) {
    if (nu == 0 || uniq[nu - 1] != uniq[i]) uniq[nu++] = uniq[i];
  }
  size_t ncuts = nu / 4u;   // cuts at uniq[4], uniq[8], ... (cut j = uniq[4 * (j + 1)])
  if (ncuts > 0 && nu % 4u == 0) ncuts--;
  size_t out_mdat_o = ftyp_n + (faststart ? moov_n : 0);
  for (size_t i = 0; i < ne; i++) {
    size_t le = 0;
    for (size_t j = 0; j < ncuts; j++) le += uniq[4u * (j + 1u)] <= eval[i];
    put_be32(moov + epos[i], (uint32_t)(out_mdat_o + (eval[i] - mdat_o) + gap * le));
  }
  size_t total = ftyp_n + moov_n + mdat_n + gap * ncuts;
  uint8_t *out = ccord_malloc(total);
  if (!out) {
    ccord_free(moov);
    return nullptr;
  }
  size_t w = 0;
  memcpy(out, in, ftyp_n), w = ftyp_n;
  if (faststart) memcpy(out + w, moov, moov_n), w += moov_n;
  size_t hdr = w;
  memcpy(out + w, in + mdat_o, 8), w += 8;
  size_t src = mdat_o + 8;
  for (size_t j = 0; j < ncuts; j++) {
    size_t cut = uniq[4u * (j + 1u)];
    memcpy(out + w, in + src, cut - src), w += cut - src, src = cut;
    memset(out + w, 0, gap), w += gap;
  }
  memcpy(out + w, in + src, mdat_o + mdat_n - src), w += mdat_o + mdat_n - src;
  put_be32(out + hdr, (uint32_t)(w - hdr));
  if (!faststart) memcpy(out + w, moov, moov_n), w += moov_n;
  ccord_free(moov);
  *out_n = w;
  return out;
}

// ---- the source under test ----

typedef struct tsrc {
  const uint8_t *data;
  int64_t len;
  pthread_mutex_t mx;
  pthread_cond_t cv;
  int delay_ms;         // sleep per read_at call, before anything else
  int64_t hold_from;    // read_at at or beyond this offset blocks until released or cancelled
  int64_t fail_from;    // read_at at or beyond this offset fails with fail_code
  int fail_code;
  bool cancelled;
  int waiting;          // readers currently blocked
  long calls, cancels, bad_off, bad_end;
  int64_t bytes;
} tsrc;

static void ms_sleep(long ms)
{
  struct timespec ts = {.tv_sec = ms / 1000, .tv_nsec = (ms % 1000) * 1000000L};
  nanosleep(&ts, nullptr);
}

static int tsrc_read_at(void *ud, int64_t off, uint8_t *buf, int n)
{
  tsrc *t = ud;
  if (t->delay_ms) ms_sleep(t->delay_ms);
  pthread_mutex_lock(&t->mx);
  t->calls++;
  if (off < 0 || n <= 0) t->bad_off++;
  if (off + n > t->len) t->bad_end++;
  if (!t->cancelled && off >= t->hold_from) {
    t->waiting++;
    while (!t->cancelled && off >= t->hold_from) pthread_cond_wait(&t->cv, &t->mx);
    t->waiting--;
  }
  int r;
  if (t->cancelled) {
    r = -(int)CCORD_ERR_IO;
  } else if (off >= t->fail_from) {
    r = -t->fail_code;
  } else if (off < 0 || off >= t->len) {
    r = 0;
  } else {
    int64_t take = t->len - off < n ? t->len - off : n;
    memcpy(buf, t->data + off, (size_t)take);
    t->bytes += take;
    r = (int)take;
  }
  pthread_mutex_unlock(&t->mx);
  return r;
}

static int64_t tsrc_size(void *ud) { return ((tsrc *)ud)->len; }

static void tsrc_cancel(void *ud)
{
  tsrc *t = ud;
  pthread_mutex_lock(&t->mx);
  t->cancelled = true;
  t->cancels++;
  pthread_cond_broadcast(&t->cv);
  pthread_mutex_unlock(&t->mx);
}

static void tsrc_init(tsrc *t, const uint8_t *data, size_t len)
{
  *t = (tsrc){.data = data, .len = (int64_t)len, .hold_from = INT64_MAX, .fail_from = INT64_MAX};
  pthread_mutex_init(&t->mx, nullptr);
  pthread_cond_init(&t->cv, nullptr);
}

static void tsrc_done(tsrc *t)
{
  pthread_cond_destroy(&t->cv);
  pthread_mutex_destroy(&t->mx);
}

static void tsrc_hold(tsrc *t, int64_t from)   // INT64_MAX releases
{
  pthread_mutex_lock(&t->mx);
  t->hold_from = from;
  pthread_cond_broadcast(&t->cv);
  pthread_mutex_unlock(&t->mx);
}

static int tsrc_waiting(tsrc *t)
{
  pthread_mutex_lock(&t->mx);
  int w = t->waiting;
  pthread_mutex_unlock(&t->mx);
  return w;
}

static bool tsrc_wait_blocked(tsrc *t, uint64_t timeout_ms)
{
  uint64_t t0 = ccord_clock_ms();
  while (ccord_clock_ms() - t0 < timeout_ms) {
    if (tsrc_waiting(t) > 0) return true;
    ms_sleep(1);
  }
  return false;
}

// Every offset the stream asked for was inside [0, size) and positive, for every source below.
static void tsrc_check_bounds(tsrc *t, const char *what)
{
  pthread_mutex_lock(&t->mx);
  long bo = t->bad_off, be = t->bad_end;
  pthread_mutex_unlock(&t->mx);
  if (bo || be) fprintf(stderr, "%s: %ld bad offsets, %ld reads past size\n", what, bo, be);
  CT_CHECK(bo == 0 && be == 0);
}

static ccord_av_stream *open_src(tsrc *t, ccord_error *err)
{
  ccord_av_source src = {.ud = t, .read_at = tsrc_read_at, .size = tsrc_size, .cancel = tsrc_cancel};
  return ccord_av_stream_open_source(&src, 0, CCORD_AV_MEDIA, err);
}

// ---- helpers ----

static uint64_t fnv(const uint8_t *p, size_t n)
{
  uint64_t h = 1469598103934665603ull;
  for (size_t i = 0; i < n; i++) h = (h ^ p[i]) * 1099511628211ull;
  return h;
}

static uint64_t frame_hash(const ccord_av_stream *s)
{
  const ccord_av_info *i = ccord_av_stream_info(s);
  const uint8_t *f = ccord_av_stream_frame(s, nullptr);
  return f && i->w > 0 && i->h > 0 ? fnv(f, (size_t)i->w * (size_t)i->h * 4u) : 0;
}

// Waits (polling, never blocking on I/O) until the state leaves OPENING.
static ccord_av_state wait_open(ccord_av_stream *s, uint64_t timeout_ms, ccord_error *err)
{
  uint64_t t0 = ccord_clock_ms();
  ccord_av_state st = ccord_av_stream_state(s, err);
  while (st == CCORD_AV_OPENING && ccord_clock_ms() - t0 < timeout_ms) {
    (void)ccord_av_stream_sync(s, 0, 0);
    ms_sleep(1);
    st = ccord_av_stream_state(s, err);
  }
  return st;
}

// Polls sync(pos) until it reports caught up.
static bool pump_to(ccord_av_stream *s, uint32_t pos, uint64_t timeout_ms)
{
  uint64_t t0 = ccord_clock_ms();
  while (ccord_clock_ms() - t0 < timeout_ms) {
    if (ccord_av_stream_sync(s, pos, 0) && ccord_av_stream_frame(s, nullptr)) return true;
    ms_sleep(1);
  }
  return false;
}

// What the memory-mode decoder shows at pos: the reference for "a frame from the right place".
static uint64_t ref_hash(uint32_t pos)
{
  ccord_error err;
  ccord_av_stream *m = ccord_av_stream_open(k_clip_end, sizeof k_clip_end, 0, CCORD_AV_MEDIA, &err);
  CT_CHECK(m != nullptr);
  if (!m) return 0;
  if (pos) ccord_av_stream_seek(m, pos);
  CT_CHECK(ccord_av_stream_sync(m, pos, 0));
  uint64_t h = frame_hash(m);
  ccord_av_stream_close(m);
  return h;
}

// ---- tests ----

static void test_arguments(void)
{
  ccord_error err;
  tsrc t;
  tsrc_init(&t, k_clip_end, sizeof k_clip_end);
  ccord_av_source ok = {.ud = &t, .read_at = tsrc_read_at, .size = tsrc_size, .cancel = tsrc_cancel};
  ccord_av_source no_read = ok;
  no_read.read_at = nullptr;
  CT_CHECK(ccord_av_stream_open_source(nullptr, 0, CCORD_AV_MEDIA, &err) == nullptr && err.code == CCORD_ERR_INVALID);
  CT_CHECK(ccord_av_stream_open_source(&no_read, 0, CCORD_AV_MEDIA, &err) == nullptr && err.code == CCORD_ERR_INVALID);
  CT_CHECK(ccord_av_stream_open_source(&ok, 0, CCORD_AV_IMAGES, &err) == nullptr && err.code == CCORD_ERR_INVALID);
  CT_CHECK(ccord_av_stream_open_source(&ok, 0, CCORD_AV_MEDIA | CCORD_AV_IMAGES, &err) == nullptr);
  CT_CHECK(ccord_av_stream_state(nullptr, &err) == CCORD_AV_FAILED);
  CT_CHECK(!ccord_av_stream_starved(nullptr));
  tsrc_done(&t);
}

// A moov-at-end clip behind a source that sleeps 20 ms per read: OPENING, then READY, while the caller keeps polling.
static void test_delayed_open(void)
{
  tsrc t;
  tsrc_init(&t, k_clip_end, sizeof k_clip_end);
  t.delay_ms = 20;
  ccord_error err;
  uint64_t t0 = ccord_clock_ms();
  ccord_av_stream *s = open_src(&t, &err);
  CT_CHECK(s != nullptr);
  if (!s) return;
  CT_CHECK(ccord_clock_ms() - t0 < 200u);   // returns at once, the probing happens on the thread
  uint64_t worst = 0;
  bool saw_opening = false, info_early = false;
  ccord_av_state st = CCORD_AV_OPENING;
  for (int i = 0; i < 5000 && st == CCORD_AV_OPENING; i++) {
    uint64_t a = ccord_clock_ms();
    const ccord_av_info *info = ccord_av_stream_info(s);
    bool nonzero = info->has_video || info->has_audio || info->duration_ms || info->w || info->h;
    bool caught = ccord_av_stream_sync(s, 0, 0);
    st = ccord_av_stream_state(s, nullptr);
    uint64_t d = ccord_clock_ms() - a;
    if (d > worst) worst = d;
    if (st == CCORD_AV_OPENING) {
      saw_opening = true;
      CT_CHECK(!caught && ccord_av_stream_starved(s) && !ccord_av_stream_ended(s));
    }
    if (nonzero && st != CCORD_AV_READY) info_early = true;
    ms_sleep(1);
  }
  CT_CHECK(saw_opening);
  CT_CHECK(!info_early);
  CT_CHECK(st == CCORD_AV_READY);
  CT_CHECK(worst <= MAX_CALL_MS);
  const ccord_av_info *info = ccord_av_stream_info(s);
  CT_CHECK(info->has_video && info->has_audio);
  CT_CHECK(info->duration_ms >= 2900u && info->duration_ms <= 3100u);
  // First frame, of the clip's size, and some audio.
  worst = 0;
  bool got = false;
  for (int i = 0; i < 5000 && !got; i++) {
    uint64_t a = ccord_clock_ms();
    bool caught = ccord_av_stream_sync(s, 0, 0);
    uint64_t d = ccord_clock_ms() - a;
    if (d > worst) worst = d;
    got = caught && ccord_av_stream_frame(s, nullptr) != nullptr;
    if (!got) ms_sleep(1);
  }
  CT_CHECK(got);
  CT_CHECK(worst <= MAX_CALL_MS);
  CT_CHECK(info->w == CLIP_W && info->h == CLIP_H);
  CT_CHECK(frame_hash(s) == ref_hash(0));
  int16_t pcm[2048];
  CT_CHECK(ccord_av_stream_read_pcm(s, pcm, 1024) > 0);
  CT_CHECK(!ccord_av_stream_starved(s));
  ccord_av_stream_close(s);
  tsrc_check_bounds(&t, "delayed_open");
  CT_CHECK(t.cancels == 1);
  tsrc_done(&t);
}

// Fast start: the first frame appears after reading far less than the whole (gapped) file.
static void test_fast_start(void)
{
  size_t n = 0;
  uint8_t *file = build_clip(true, GAP_BYTES, &n);
  CT_CHECK(file != nullptr);
  if (!file) return;
  CT_CHECK(n > 400u * 1024u);
  tsrc t;
  tsrc_init(&t, file, n);
  t.hold_from = (int64_t)n / 2;   // the read-ahead cannot run on: the frame must come from the first half
  ccord_error err;
  ccord_av_stream *s = open_src(&t, &err);
  CT_CHECK(s != nullptr);
  if (s) {
    CT_CHECK(wait_open(s, 5000, &err) == CCORD_AV_READY);
    CT_CHECK(pump_to(s, 0, 5000));
    int64_t before;
    pthread_mutex_lock(&t.mx);
    before = t.bytes;
    pthread_mutex_unlock(&t.mx);
    CT_CHECK(before > 0 && before < (int64_t)n / 2 + 40 * 1024);   // a read that starts before the hold may run past it
    CT_CHECK(ccord_av_stream_info(s)->w == CLIP_W && ccord_av_stream_info(s)->h == CLIP_H);
    CT_CHECK(frame_hash(s) == ref_hash(0));
    tsrc_hold(&t, INT64_MAX);   // let it read on: the whole clip plays through
    CT_CHECK(pump_to(s, 2900, 5000));
    ccord_av_stream_close(s);
  }
  tsrc_check_bounds(&t, "fast_start");
  tsrc_done(&t);
  ccord_free(file);
}

// A seek while the demux thread is blocked inside read_at returns at once; the frame shown afterwards is from the
// position of the last seek, never from the first one or from before.
static void test_seek_during_blocked_read(void)
{
  size_t n = 0;
  uint8_t *file = build_clip(true, GAP_BYTES, &n);
  CT_CHECK(file != nullptr);
  if (!file) return;
  uint64_t h0 = ref_hash(0), h1500 = ref_hash(1500), h2000 = ref_hash(2000);
  CT_CHECK(h0 != h1500 && h1500 != h2000 && h0 != h2000);
  tsrc t;
  tsrc_init(&t, file, n);
  ccord_error err;
  ccord_av_stream *s = open_src(&t, &err);
  CT_CHECK(s != nullptr);
  if (s) {
    CT_CHECK(wait_open(s, 5000, &err) == CCORD_AV_READY);
    CT_CHECK(pump_to(s, 0, 5000));
    uint32_t serial0 = 0;
    (void)ccord_av_stream_frame(s, &serial0);
    tsrc_hold(&t, 0);   // from now on every read_at blocks
    ccord_av_stream_seek(s, 1500);
    CT_CHECK(ccord_av_stream_starved(s));
    CT_CHECK(tsrc_wait_blocked(&t, 3000));   // the demux thread is parked inside read_at
    uint64_t a = ccord_clock_ms();
    ccord_av_stream_seek(s, 2000);           // posted while it is blocked
    CT_CHECK(ccord_clock_ms() - a <= MAX_CALL_MS);
    CT_CHECK(ccord_av_stream_starved(s));
    for (int i = 0; i < 10; i++) {   // nothing can be decoded: not caught up, and says why
      CT_CHECK(!ccord_av_stream_sync(s, 2000, 0));
      CT_CHECK(ccord_av_stream_starved(s));
      ms_sleep(2);
    }
    CT_CHECK(tsrc_waiting(&t) > 0);
    tsrc_hold(&t, INT64_MAX);
    CT_CHECK(pump_to(s, 2000, 5000));
    uint32_t serial1 = 0;
    (void)ccord_av_stream_frame(s, &serial1);
    CT_CHECK(serial1 != serial0);
    CT_CHECK(!ccord_av_stream_starved(s));
    uint64_t got = frame_hash(s);
    CT_CHECK(got == h2000);
    CT_CHECK(got != h1500 && got != h0);
    // And a seek back across the clip works the same way once nothing is blocked.
    ccord_av_stream_seek(s, 1500);
    CT_CHECK(pump_to(s, 1500, 5000));
    CT_CHECK(frame_hash(s) == h1500);
    ccord_av_stream_close(s);
  }
  tsrc_check_bounds(&t, "seek_blocked");
  tsrc_done(&t);
  ccord_free(file);
}

// Withheld bytes: sync is not "caught up", starved says so; when the bytes arrive it clears and frames flow.
static void test_starved(void)
{
  size_t n = 0;
  uint8_t *file = build_clip(true, GAP_BYTES, &n);
  CT_CHECK(file != nullptr);
  if (!file) return;
  tsrc t;
  tsrc_init(&t, file, n);
  t.hold_from = (int64_t)n / 2;   // the second half of the file is withheld
  ccord_error err;
  ccord_av_stream *s = open_src(&t, &err);
  CT_CHECK(s != nullptr);
  if (s) {
    CT_CHECK(wait_open(s, 5000, &err) == CCORD_AV_READY);
    CT_CHECK(pump_to(s, 0, 5000));
    CT_CHECK(!ccord_av_stream_starved(s));
    bool starved = false;
    uint64_t t0 = ccord_clock_ms();
    while (!starved && ccord_clock_ms() - t0 < 5000) {   // play on until the withheld part is needed
      bool caught = ccord_av_stream_sync(s, 2800, 0);
      starved = !caught && ccord_av_stream_starved(s);
      if (!starved) ms_sleep(1);
    }
    CT_CHECK(starved);
    CT_CHECK(tsrc_wait_blocked(&t, 3000));
    for (int i = 0; i < 20; i++) {
      CT_CHECK(!ccord_av_stream_sync(s, 2800, 0));
      CT_CHECK(ccord_av_stream_starved(s));
      ms_sleep(1);
    }
    tsrc_hold(&t, INT64_MAX);
    CT_CHECK(pump_to(s, 2800, 5000));
    CT_CHECK(!ccord_av_stream_starved(s));
    CT_CHECK(frame_hash(s) != 0);
    ccord_av_stream_close(s);
  }
  tsrc_check_bounds(&t, "starved");
  tsrc_done(&t);
  ccord_free(file);
}

// Closing while the demux thread is parked inside read_at cancels the source and joins within 2 s.
static void test_close_blocked(void)
{
  size_t n = 0;
  uint8_t *file = build_clip(true, GAP_BYTES, &n);
  CT_CHECK(file != nullptr);
  if (!file) return;
  ccord_error err;
  {   // blocked while opening
    tsrc t;
    tsrc_init(&t, file, n);
    t.hold_from = 0;
    ccord_av_stream *s = open_src(&t, &err);
    CT_CHECK(s != nullptr);
    if (s) {
      CT_CHECK(tsrc_wait_blocked(&t, 3000));
      CT_CHECK(ccord_av_stream_state(s, nullptr) == CCORD_AV_OPENING);
      uint64_t a = ccord_clock_ms();
      ccord_av_stream_close(s);
      CT_CHECK(ccord_clock_ms() - a < 2000u);
      CT_CHECK(t.cancels == 1);
    }
    tsrc_done(&t);
  }
  {   // blocked mid-playback, by a seek
    tsrc t;
    tsrc_init(&t, file, n);
    ccord_av_stream *s = open_src(&t, &err);
    CT_CHECK(s != nullptr);
    if (s) {
      CT_CHECK(wait_open(s, 5000, &err) == CCORD_AV_READY);
      CT_CHECK(pump_to(s, 0, 5000));
      tsrc_hold(&t, 0);
      ccord_av_stream_seek(s, 2000);
      CT_CHECK(tsrc_wait_blocked(&t, 3000));
      uint64_t a = ccord_clock_ms();
      ccord_av_stream_close(s);
      CT_CHECK(ccord_clock_ms() - a < 2000u);
      CT_CHECK(t.cancels == 1);
    }
    tsrc_done(&t);
  }
  {   // closed straight after open, before the thread got anywhere
    tsrc t;
    tsrc_init(&t, file, n);
    t.delay_ms = 5;
    ccord_av_stream *s = open_src(&t, &err);
    CT_CHECK(s != nullptr);
    ccord_av_stream_close(s);
    tsrc_done(&t);
  }
  ccord_free(file);
}

static void expect_failed(tsrc *t, ccord_status want, const char *what)
{
  ccord_error err;
  ccord_av_stream *s = open_src(t, &err);
  CT_CHECK(s != nullptr);
  if (!s) return;
  uint64_t t0 = ccord_clock_ms();
  ccord_av_state st = CCORD_AV_OPENING;
  ccord_error why;
  ccord_error_clear(&why);
  while (ccord_clock_ms() - t0 < 5000) {   // keep playing while the source fails underneath
    (void)ccord_av_stream_sync(s, 0, 0);
    (void)ccord_av_stream_frame(s, nullptr);
    st = ccord_av_stream_state(s, &why);
    if (st == CCORD_AV_FAILED) break;
    ms_sleep(1);
  }
  if (st != CCORD_AV_FAILED || why.code != want) fprintf(stderr, "%s: state=%d code=%d\n", what, (int)st, (int)why.code);
  CT_CHECK(st == CCORD_AV_FAILED);
  CT_CHECK(why.code == want);
  CT_CHECK(why.message[0] != '\0');
  CT_CHECK(ccord_av_stream_state(s, nullptr) == CCORD_AV_FAILED);   // one-way
  CT_CHECK(ccord_av_stream_sync(s, 500, 0));   // nothing will arrive: not "buffering"
  CT_CHECK(!ccord_av_stream_starved(s));
  CT_CHECK(ccord_av_stream_ended(s));
  ccord_av_stream_seek(s, 100);   // harmless
  CT_CHECK(ccord_av_stream_state(s, nullptr) == CCORD_AV_FAILED);
  ccord_av_stream_close(s);
}

static void test_failures(void)
{
  size_t n = 0;
  uint8_t *file = build_clip(true, GAP_BYTES, &n);
  CT_CHECK(file != nullptr);
  if (!file) return;
  tsrc t;
  tsrc_init(&t, file, n);   // no Range support: the very first read says so
  t.fail_from = 0;
  t.fail_code = (int)CCORD_ERR_UNSUPPORTED;
  expect_failed(&t, CCORD_ERR_UNSUPPORTED, "unsupported");
  tsrc_done(&t);
  tsrc_init(&t, file, n);   // an I/O error while opening
  t.fail_from = 0;
  t.fail_code = (int)CCORD_ERR_IO;
  expect_failed(&t, CCORD_ERR_IO, "io at open");
  tsrc_done(&t);
  tsrc_init(&t, file, n);   // fails in the middle of the file, while playing
  t.fail_from = (int64_t)n / 2;
  t.fail_code = (int)CCORD_ERR_TIMEOUT;
  expect_failed(&t, CCORD_ERR_TIMEOUT, "mid-file");
  tsrc_check_bounds(&t, "failures");
  tsrc_done(&t);
  ccord_free(file);
}

// Garbage behind a source ends in FAILED (unsupported format), not a hang.
static void test_garbage(void)
{
  static uint8_t junk[4096];
  for (size_t i = 0; i < sizeof junk; i++) junk[i] = (uint8_t)(i * 131u + 7u);
  tsrc t;
  tsrc_init(&t, junk, sizeof junk);
  ccord_error err;
  ccord_av_stream *s = open_src(&t, &err);
  CT_CHECK(s != nullptr);
  if (s) {
    ccord_error why;
    CT_CHECK(wait_open(s, 5000, &why) == CCORD_AV_FAILED);
    CT_CHECK(why.code == CCORD_ERR_UNSUPPORTED);
    ccord_av_stream_close(s);
  }
  tsrc_done(&t);
}

int main(void)
{
  test_arguments();
  test_delayed_open();
  test_fast_start();
  test_seek_during_blocked_read();
  test_starved();
  test_close_blocked();
  test_failures();
  test_garbage();
  return CT_RESULT("test_av_source");
}
